package com.wangzan101.mika.core.decision

import com.wangzan101.mika.core.model.Part
import com.wangzan101.mika.core.record.Redactor
import com.wangzan101.mika.core.uistate.PressKeys
import kotlinx.serialization.json.*

/** Planner/actor handoff. No text, commands or coordinates are generated by the decision service. */
class OperationCoordinator(private val decision: DecisionPort, val mode: FastMode) {
    var plan: OperationPlan? = null
        private set
    private var userGoal = ""
    private var actions = 0
    private val usedPrepared = mutableSetOf<Int>()
    private val recent = ArrayDeque<String>()
    private val repeated = mutableMapOf<String, Int>()
    private var pendingPrepared: Int? = null
    private var pendingSummary: String? = null
    private var pendingNotice: String? = null
    private var needsPlanner = false
    private var handoffPrompted = false
    private var failureKey: String? = null
    private var failures = 0
    private var lastStateToken: String? = null
    val planState: String get() = if (plan == null) "needs_plan" else if (needsPlanner) "recovering" else "active"

    fun install(raw: String, offered: Set<String>, goal: String, bindSnapshot: (String, String) -> String? = { _, _ -> null }) {
        reset()
        if (OperationPlanning.releases(raw)) { handoffPrompted = true; userGoal = goal; return }
        val next = OperationPlanning.parse(raw, offered, bindSnapshot)
        plan = next; userGoal = goal
    }
    fun reset() {
        plan = null; userGoal = ""; actions = 0; usedPrepared.clear(); recent.clear(); repeated.clear(); pendingPrepared = null; pendingSummary = null
        pendingNotice = null; needsPlanner = false; handoffPrompted = false; failureKey = null; failures = 0; lastStateToken = null
    }
    fun goalChanged(goal: String) { if (userGoal.isNotEmpty() && goal != userGoal) reset(); userGoal = goal }

    private fun finishPhase(reason: String) {
        val goal = userGoal
        reset()
        userGoal = goal
        handoffPrompted = true
        pendingNotice = "JEV phase returned: $reason. Review the evidence. If more UI execution is needed, submit the next operation_plan instead of manually executing each UI step."
        needsPlanner = true
    }

    /** Give the planner one recovery turn, then resume the retained phase on a new observation. */
    fun recover(reason: String, detail: DecisionFailure? = null) {
        if (plan == null) return
        pendingPrepared = null; pendingSummary = null
        val key = "$lastStateToken:$reason:${detail?.question}"
        failures = if (key == failureKey) failures + 1 else 1
        failureKey = key
        if (failures >= 3) { finishPhase("replan_after_repeated_$reason"); return }
        needsPlanner = true
        pendingNotice = (if (reason == "action_failed")
            "The last executed tool reported action_failed; effects may be partial. Inspect fresh evidence before repeating it."
            else "JEV did not execute an action: $reason.") + (detail?.let {
            " Question=${it.question}, probability=${it.probability}, runnerUp=${it.runnerUp}, requiredProbability=${it.minProbability}, requiredMargin=${it.minMargin}."
        } ?: "") + " The current phase is retained. Perform a recovery tool call or replace operation_plan; JEV will automatically try the fresh page after your tool call. For extended reading/reasoning or to abandon this phase, call operation_plan with {\"control\":\"release\"}. A handoff is not evidence that an action happened."
    }

    fun takePlannerNotice(): String? {
        val notice = pendingNotice
        pendingNotice = null; needsPlanner = false
        return notice
    }

    fun after(tool: String, ok: Boolean, changed: Boolean?, guard: Boolean, byDecision: Boolean = true) {
        if (mode == FastMode.Off) return
        if (plan == null) {
            if (mode == FastMode.Enabled && !byDecision && ok && !handoffPrompted &&
                (tool.startsWith("phone_") || tool.startsWith("web_"))) {
                handoffPrompted = true; needsPlanner = true
                pendingNotice = "UI tools are now in use. For the remaining app/web execution, submit operation_plan with a useful phase and its relevant actions before continuing individual UI operations. If the task is already complete, verify it and finish."
            }
            return
        }
        if (byDecision) actions++
        if (byDecision) pendingPrepared?.let(usedPrepared::add)
        pendingPrepared = null
        recent += "${pendingSummary ?: tool}: ${if (ok) "ok" else "failed"}, changed=${changed ?: "unknown"}"
        pendingSummary = null
        while (recent.size > 8) recent.removeFirst()
        if (guard) finishPhase("guard_or_user_handoff")
        else if (!ok) recover("action_failed")
        else if (changed == true) { failureKey = null; failures = 0 }
    }

    suspend fun propose(goal: String, screen: JsonObject?, offered: Set<String>, apps: Map<String, String>, step: Int): FastAttempt {
        goalChanged(goal)
        val phase = plan ?: return FastAttempt(false, reason = "needs_plan")
        if (mode == FastMode.Off) return FastAttempt(false)
        if (needsPlanner) return FastAttempt(false, reason = "planner_recovery")
        if (actions >= phase.maxActions) { finishPhase("phase_review"); return FastAttempt(false, reason = "phase_review") }
        val state = screen ?: buildJsonObject { put("ok", false); put("surface", phase.surface) }
        lastStateToken = state.string("stateToken")
        val table = questions(phase, state, offered, apps, usedPrepared)
        if (table.questions.getValue("operation").choices.size < 2) { finishPhase("no_actions"); return FastAttempt(false, reason = "no_actions") }
        val answer = choose(goal, phase, state, table)
        if (answer !is DecisionBatchAttempt.Pick) {
            val failure = answer as DecisionBatchAttempt.Abstain
            if (failure.reason in setOf("authentication", "missing_key", "rate_limited", "cooldown", "invalid_input")) finishPhase(failure.reason)
            else recover(failure.reason, failure.detail)
            return FastAttempt(true, reason = failure.reason)
        }
        val operation = answer.values.getValue("operation")
        if (operation == "return_to_planner") { finishPhase("planner_review"); return FastAttempt(true, reason = "planner_review") }
        val action = resolve(operation, answer.values, phase, state, offered, apps, usedPrepared)
            ?: run { recover("invalid_arguments"); return FastAttempt(true, reason = "invalid_arguments") }
        val token = state.string("stateToken")
        // Ignore read IDs: changing only the observation number must not permit an endless loop.
        val identity = token.orEmpty() + ":" + action.first + ":" + JsonObject(action.second.filterKeys { it != "snapshotId" })
        if (repeated.getOrDefault(identity, 0) >= 2) { finishPhase("no_progress"); return FastAttempt(true, reason = "no_progress") }
        repeated[identity] = repeated.getOrDefault(identity, 0) + 1
        pendingPrepared = if (operation == "prepared" && mode != FastMode.Shadow) answer.values["prepared"]?.removePrefix("call_")?.toIntOrNull() else null
        pendingSummary = if (mode == FastMode.Shadow) null else answer.values.toString()
        val binding = token.takeUnless { operation == "open_app" || operation == "prepared" &&
            !action.first.startsWith("${phase.surface}_") }
        val pick = ChoiceAttempt.Pick(operation, answer.model, answer.elapsedMs)
        return FastAttempt(true, StepProposal.Decision(Part.ToolCall("decision-$step", action.first, action.second.toString()),
            pick, binding, planned = true), if (mode == FastMode.Shadow) "shadow" else "accepted")
    }

    private suspend fun choose(goal: String, phase: OperationPlan, state: JsonObject, table: Questions): DecisionBatchAttempt {
        val payload = requestState(goal, phase, state, recent.toList(), table)
        if (!splitNeeded(payload, table)) return decision.attemptBatch(DecisionBatchInput("operation", Redactor.text(payload.toString()),
            table.questions, "operation", table.branches, "operations-v2"))
        // Large pages: do not ask for every target/key/app before knowing which operation needs them.
        val route = decision.attemptBatch(DecisionBatchInput("operation", Redactor.text(payload.toString()),
            table.questions.filterKeys { it == "operation" }, "operation", table.branches.mapValues { emptySet() }, "operations-v2", stage = "route"))
        if (route !is DecisionBatchAttempt.Pick) return route
        val operation = route.values.getValue("operation")
        val required = table.branches.getValue(operation)
        if (required.isEmpty()) return route
        val qs = table.questions.filterKeys { it in required }
        val first = qs.keys.first()
        val focused = focusedState(payload, operation, required)
        val parameters = decision.attemptBatch(DecisionBatchInput("operation", Redactor.text(focused.toString()), qs, first,
            qs.getValue(first).choices.mapValues { required - first }, "operations-v2", stage = "parameters"))
        return if (parameters is DecisionBatchAttempt.Pick) parameters.copy(values = parameters.values + ("operation" to operation),
            elapsedMs = route.elapsedMs + parameters.elapsedMs) else parameters
    }

    data class Questions(val questions: Map<String, DecisionQuestion>, val branches: Map<String, Set<String>>)

    companion object {
        private const val NONE = "unavailable"
        private val DIRECTIONS = linkedMapOf("up" to "Up", "down" to "Down", "left" to "Left", "right" to "Right")

        private fun focusedState(payload: JsonObject, operation: String, required: Set<String>): JsonObject {
            val focus = payload.filterKeys { key -> when (key) {
            "installedApps" -> operation == "open_app"
            "texts" -> operation == "type_text"
            "prepared" -> operation == "prepared"
            else -> true
            } }.toMutableMap()
            if (required.none { it in setOf("target", "to_target", "field", "prepared") }) {
                val screen = payload.getValue("screen").jsonObject
                val all = (screen["elements"] as? JsonArray).orEmpty()
                val relevant = all.filter { item ->
                    val e = item.jsonObject
                    "direction" in required && e["scrollable"] == JsonPrimitive(true) ||
                        "key" in required && (e["focused"] == JsonPrimitive(true) || e["editable"] == JsonPrimitive(true))
                }
                focus["screen"] = JsonObject(screen + mapOf("elements" to JsonArray(relevant), "elementsOmitted" to JsonPrimitive(all.size - relevant.size)))
            }
            return JsonObject(focus + ("selectedOperation" to JsonPrimitive(operation)))
        }

        fun splitNeeded(payload: JsonObject, table: Questions): Boolean = table.questions.size > 1 &&
            (table.questions.values.sumOf { it.choices.size } > 96 || payload.toString().length.toLong() * table.questions.size > 24_000)

        /** Keep labels/states/position once. Tokens and geometry used only by the executor stay local. */
        private fun compactScreen(screen: JsonObject): JsonObject = JsonObject(screen.filterKeys { it !in setOf("stateToken", "snapshotId", "elements") } +
            ("elements" to JsonArray(elements(screen).map { e -> buildJsonObject {
                for (key in listOf("ref", "name", "role", "center")) e[key]?.let { put(key, it) }
                for (key in listOf("clickable", "editable", "scrollable", "focused")) if (e[key] == JsonPrimitive(true)) put(key, true)
                for (key in listOf("states", "matchesTextValues")) (e[key] as? JsonArray)?.takeIf { it.isNotEmpty() }?.let { put(key, it) }
            } })))

        /** Questions cannot see each other's criteria: routing needs the available apps and prepared calls too. */
        fun requestState(goal: String, phase: OperationPlan, screen: JsonObject, recent: List<String>, table: Questions) = buildJsonObject {
            put("userGoal", goal); put("objective", phase.objective); put("doneWhen", phase.doneWhen)
            put("screen", compactScreen(screen)); put("recentActions", JsonArray(recent.map(::JsonPrimitive)))
            if ("text" in table.questions) put("texts", JsonObject(phase.texts.mapValues { JsonPrimitive(it.value) }))
            table.questions["app"]?.let { put("installedApps", JsonObject(it.choices.filterKeys { key -> key != NONE }.mapValues { JsonPrimitive(it.value) })) }
            table.questions["prepared"]?.let { q -> put("prepared", JsonObject(phase.prepared.withIndex()
                .filter { "call_${it.index}" in q.choices }.associate { "call_${it.index}" to buildJsonObject {
                    put("tool", it.value.tool); put("whenToUse", it.value.whenToUse)
                } })) }
        }

        fun questions(phase: OperationPlan, screen: JsonObject, offered: Set<String>, apps: Map<String, String>, used: Set<Int> = emptySet()): Questions {
            val questions = linkedMapOf<String, DecisionQuestion>()
            val branches = linkedMapOf("return_to_planner" to emptySet<String>())
            val operations = linkedMapOf("return_to_planner" to "The phase's doneWhen is evidenced, or new reasoning, content reading, missing values or recovery is needed. Return to the reasoning model; do not claim the whole task is complete.")
            val elements = elements(screen)
            val targets = elements.associate { it.string("ref")!! to "Element ${it.string("ref")} in screen.elements" }
            val fields = elements.filter { it["editable"] == JsonPrimitive(true) }.associate { it.string("ref")!! to "Input ${it.string("ref")} in screen.elements" }
            fun question(id: String, wording: String, choices: Map<String, String>) {
                questions[id] = DecisionQuestion(wording, if (choices.size == 1) choices + (NONE to "No matching value") else choices)
            }
            fun action(id: String, tool: String, description: String, vararg required: String) {
                if (tool !in offered || phase.actions.isNotEmpty() && id !in phase.actions) return
                operations[id] = description; branches[id] = required.toSet()
            }
            val surface = phase.surface
            if (screen["ok"] == JsonPrimitive(true) && screen.string("stateToken") != null) {
                if (targets.isNotEmpty()) {
                    question("target", DecisionQuestions.OPERATION_TARGET, targets)
                    question("to_target", DecisionQuestions.DRAG_TARGET, targets)
                    action("tap", "${surface}_tap", "Tap a visible element once, including buttons, links, menu entries, checkboxes or switches.", "target")
                    action("double_tap", "${surface}_tap", "Double-tap a visible element.", "target")
                    action("long_press", "${surface}_swipe", "Hold down on a visible element for 900 milliseconds without moving.", "target")
                    if (surface == "web") {
                        action("drag", "web_interact", "Drag a visible element onto another visible element.", "target", "to_target")
                        action("hover", "web_interact", "Move the pointer over a visible element.", "target")
                    } else action("drag", "phone_swipe", "Slowly drag from one visible element to another (without a separate initial hold).", "target", "to_target")
                }
                if (fields.isNotEmpty()) {
                    question("field", DecisionQuestions.INPUT_FIELD, fields)
                    if (phase.texts.isNotEmpty()) {
                        question("text", DecisionQuestions.INPUT_VALUE, phase.texts.mapValues { "Exact value at texts.${it.key}" })
                        action("type_text", "${surface}_type_text", "Focus the selected input field and fill it with an exact value from texts in one operation; no separate tap is needed. No Enter key is included.", "field", "text")
                    }
                    action("clear_text", "${surface}_clear_text", "Clear an input field.", "field")
                }
                question("direction", DecisionQuestions.GESTURE_DIRECTION, DIRECTIONS)
                action("scroll", "${surface}_scroll", "Scroll to reveal content in the requested direction (down means later content, finger moves up).", "direction")
                action("swipe", "${surface}_swipe", "Move the finger across the screen in a direction, for a swipe gesture rather than reading more content.", "direction")
                action("back", "${surface}_back", "Go back one page.")
                question("key", DecisionQuestions.OPERATION_KEY, PressKeys.BY_NAME.mapValues { it.key.removePrefix("KEYCODE_") })
                action("press_key", "${surface}_press_key", "Press a navigation or editing key, including Enter when the planned input is ready.", "key")
                if (surface == "phone") {
                    action("zoom_in", "phone_gesture", "Spread two fingers around the screen center to zoom in.")
                    action("zoom_out", "phone_gesture", "Pinch two fingers toward the screen center to zoom out.")
                }
            }
            val installed = appChoices(apps, phase)
            if (surface == "phone" && installed.isNotEmpty()) {
                question("app", DecisionQuestions.OPERATION_APP, installed)
                action("open_app", "phone_launch_app", "Open or switch to an app in installedApps needed for the current phase.", "app")
            }
            val prepared = phase.prepared.withIndex().filter { it.index !in used && it.value.tool in offered &&
                (it.value.stateToken == null || it.value.stateToken == screen.string("stateToken")) }
                .associate { "call_${it.index}" to "Prepared call_${it.index} in prepared" }
            if (prepared.isNotEmpty() && (phase.actions.isEmpty() || "prepared" in phase.actions)) {
                question("prepared", DecisionQuestions.PREPARED_OPERATION, prepared)
                operations["prepared"] = "Execute one exact tool call supplied by the reasoning model when its condition holds."
                branches["prepared"] = setOf("prepared")
            }
            // Do not send unused questions; the service answers all sent questions independently.
            val required = branches.values.flatten().toSet()
            return Questions(mapOf("operation" to DecisionQuestion(DecisionQuestions.OPERATION, operations)) + questions.filterKeys { it in required }, branches)
        }

        private fun resolve(operation: String, values: Map<String, String>, phase: OperationPlan, screen: JsonObject,
                            offered: Set<String>, apps: Map<String, String>, used: Set<Int>): Pair<String, JsonObject>? = runCatching {
            val surface = phase.surface
            val elements = elements(screen).associateBy { it.string("ref")!! }
            val snapshot = screen.string("snapshotId")
            fun target(key: String): JsonObject = elements.getValue(values.getValue(key))
            fun ref(key: String): JsonObject = buildJsonObject { put("ref", target(key).string("ref")); put("snapshotId", snapshot ?: error("no_snapshot")) }
            fun point(e: JsonObject): Pair<Int, Int> {
                val center = e["center"] as? JsonObject ?: error("no_center")
                val x = (center["x"] as? JsonPrimitive)?.intOrNull ?: error("no_x")
                val y = (center["y"] as? JsonPrimitive)?.intOrNull ?: error("no_y")
                require(x in 0..999 && y in 0..999); return x to y
            }
            fun swipe(from: Pair<Int, Int>, to: Pair<Int, Int>, ms: Int) = buildJsonObject {
                put("startX", from.first); put("startY", from.second); put("endX", to.first); put("endY", to.second); put("durationMs", ms)
            }
            val result = when (operation) {
                "tap", "double_tap" -> "${surface}_tap" to JsonObject(ref("target") + ("clicks" to JsonPrimitive(if (operation == "tap") 1 else 2)))
                "long_press" -> "${surface}_swipe" to point(target("target")).let { swipe(it, it, 900) }
                "drag" -> {
                    require(values["target"] != values["to_target"])
                    if (surface == "web") "web_interact" to JsonObject(ref("target") + mapOf("action" to JsonPrimitive("drag"), "toRef" to JsonPrimitive(values.getValue("to_target"))))
                    else "phone_swipe" to swipe(point(target("target")), point(target("to_target")), 1200)
                }
                "hover" -> "web_interact" to JsonObject(ref("target") + ("action" to JsonPrimitive("hover")))
                "type_text", "clear_text" -> {
                    require(target("field")["editable"] == JsonPrimitive(true))
                    "${surface}_$operation" to JsonObject(ref("field") + if (operation == "type_text")
                        mapOf("text" to JsonPrimitive(phase.texts.getValue(values.getValue("text")))) else emptyMap())
                }
                "scroll" -> "${surface}_scroll" to buildJsonObject {
                    put("direction", values.getValue("direction")); put("amount", when (phase.gestureAmount) { "small" -> 1; "large" -> 6; else -> 3 })
                }
                "swipe" -> {
                    val d = when (phase.gestureAmount) { "small" -> 100; "large" -> 325; else -> 200 }
                    val (dx, dy) = when (values.getValue("direction")) { "up" -> 0 to -d; "down" -> 0 to d; "left" -> -d to 0; "right" -> d to 0; else -> error("direction") }
                    "${surface}_swipe" to swipe(500 - dx to 500 - dy, 500 + dx to 500 + dy, 400)
                }
                "back" -> "${surface}_back" to buildJsonObject { }
                "press_key" -> "${surface}_press_key" to buildJsonObject { put("key", values.getValue("key")) }
                "open_app" -> {
                    val pkg = values.getValue("app"); require(pkg in appChoices(apps, phase))
                    "phone_launch_app" to buildJsonObject { put("package", pkg) }
                }
                "zoom_in", "zoom_out" -> "phone_gesture" to buildJsonObject {
                    val start = if (operation == "zoom_in") 70 else 230
                    val end = if (operation == "zoom_in") 230 else 70
                    putJsonArray("paths") { for (sign in listOf(-1, 1)) add(buildJsonArray {
                        add(buildJsonArray { add(500 + sign * start); add(500) }); add(buildJsonArray { add(500 + sign * end); add(500) })
                    }) }; put("durationMs", 500)
                }
                "prepared" -> {
                    val index = values.getValue("prepared").removePrefix("call_").toInt(); require(index !in used)
                    val p = phase.prepared[index]; require(p.stateToken == null || p.stateToken == screen.string("stateToken")); p.tool to p.args
                }
                else -> error("unknown_operation")
            }
            require(result.first in offered)
            result
        }.getOrNull()

        private fun appChoices(apps: Map<String, String>, phase: OperationPlan): Map<String, String> {
            val valid = apps.entries.filter { com.wangzan101.mika.core.tool.PACKAGE_NAME_RE.matches(it.key) }
            val named = valid.filter { phase.objective.contains(it.key, ignoreCase = true) ||
                it.value.isNotBlank() && phase.objective.contains(it.value, ignoreCase = true) }
            return (named.ifEmpty { valid }).take(254).associate { it.key to it.value.take(100) }
        }
        private fun elements(screen: JsonObject): List<JsonObject> = (screen["elements"] as? JsonArray).orEmpty().mapNotNull { it as? JsonObject }
            .filter { it.string("ref")?.startsWith("@") == true && it["secret"] != JsonPrimitive(true) && it["disabled"] != JsonPrimitive(true) }
            .distinctBy { it.string("ref") }.take(120)
        private fun JsonObject.string(key: String) = (get(key) as? JsonPrimitive)?.contentOrNull
    }
}
